package com.example

/**
 * Complete, distinct 20 cards for Mathematics Sets 10 to 15 (120 unique cards).
 * Covers Circle Theorems, Congruence & Similarity, Probability, Statistics, Commercial Math, and Matrices & Sets.
 */
object FlashcardBankMathsSetsPart2 {




  // Sets 17-20 content implementation follows below...

  fun getMathSet(setNum: Int, cardNum: Int, grade: String): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      10 -> if (grade == "11") mathSet10Gr11[(c - 1) % 20] else mathSet10Gr10[(c - 1) % 20]
      11 -> if (grade == "11") mathSet11Gr11[(c - 1) % 20] else mathSet11Gr10[(c - 1) % 20]
      12 -> if (grade == "11") mathSet12Gr11[(c - 1) % 20] else mathSet12Gr10[(c - 1) % 20]
      13 -> if (grade == "11") mathSet13Gr11[(c - 1) % 20] else mathSet13Gr10[(c - 1) % 20]
      14 -> if (grade == "11") mathSet14Gr11[(c - 1) % 20] else mathSet14Gr10[(c - 1) % 20]
      15 -> if (grade == "11") mathSet15Gr11[(c - 1) % 20] else mathSet15Gr10[(c - 1) % 20]
      16 -> if (grade == "11") mathSet16Gr11[(c - 1) % 20] else mathSet16Gr10[(c - 1) % 20]
      17 -> if (grade == "11") mathSet17Gr11[(c - 1) % 20] else mathSet17Gr10[(c - 1) % 20]
      18 -> if (grade == "11") mathSet18Gr11[(c - 1) % 20] else mathSet18Gr10[(c - 1) % 20]
      19 -> if (grade == "11") mathSet19Gr11[(c - 1) % 20] else mathSet19Gr10[(c - 1) % 20]
      20 -> if (grade == "11") mathSet20Gr11[(c - 1) % 20] else mathSet20Gr10[(c - 1) % 20]
      else -> null
    } as CardContentTuple?
  }







